content.content:
1	/**
2	 * T2.5 poll reconciliation.
3	 *
4	 * Webhooks get dropped, so polling is the safety net that makes a lost
5	 * delivery survivable. A dispatched run carries `poll_after` and the tick
6	 * advances it by re-fetching the authoritative call. Follow-up crosses tick
7	 * boundaries rather than looping, because a free Edge Function allows 150
8	 * seconds of wall clock per request.
9	 *
10	 * Whichever of the webhook and the poll arrives first wins. Every write here
11	 * is a conditional PATCH that only matches a still-pending run, so the second
12	 * arrival changes nothing and records nothing.
13	 *
14	 * This module sets a terminal `state` and deliberately leaves `completed_at`
15	 * null. The tick's finaliser owns `completed_at` and the ingestion that
16	 * follows, because `terminalRuns()` selects terminal runs with a null
17	 * `completed_at`, and a poll must not shortcut that.
18	 */
19	
20	import type { CalleDeps } from "./calle.ts";
21	import { recordCallEvent } from "./events.ts";
22	import type { CallStatus, CallTaskFixture } from "./fixtures.ts";
23	
24	/** The first follow-up is set by dispatch. Each pass after that waits ten. */
25	export const POLL_INTERVAL_MS = 10_000;
26	
27	/**
28	 * A run the provider never resolves is worse than a failed one, because it is
29	 * invisible. Give up well past the 140 seconds a real call took, and name the
30	 * reason on the run so an operator sees where it stopped.
31	 */
32	export const POLL_GIVE_UP_MS = 15 * 60_000;
33	
34	/** The terminal states the provider can report, mapped onto `call_runs.state`. */
35	export type TerminalState = "completed" | "failed" | "canceled";
36	
37	export type PollableRun = {
38	  id: string;
39	  state: string;
40	  poll_after: string | null;
41	};
42	
43	type RunRow = {
44	  id: string;
45	  state: string;
46	  calle_call_id: string | null;
47	  dispatched_at: string | null;
48	  poll_after: string | null;
49	};
50	
51	const PENDING_STATES = "in.(dispatched,awaiting_result)";
52	
53	function restUrl(base: string, path: string, query = ""): string {
54	  return `${base.replace(/\/+$/, "")}/rest/v1/${path}${query ? `?${query}` : ""}`;
55	}
56	
57	function serviceHeaders(key: string, prefer?: string): HeadersInit {
58	  const headers: Record<string, string> = {
59	    apikey: key,
60	    authorization: `Bearer ${key}`,
61	    "content-type": "application/json",
62	  };
63	  if (prefer) headers.prefer = prefer;
64	  return headers;
65	}
66	
67	export function terminalStateFor(status: CallStatus): TerminalState | null {
68	  if (status === "completed") return "completed";
69	  if (status === "failed") return "failed";
70	  if (status === "canceled") return "canceled";
71	  return null;
72	}
73	
74	/**
75	 * Re-fetches one authoritative call. It carries no run-state side effect, so
76	 * the tick's finaliser can reuse it for a run the webhook already terminalised.
77	 */
78	export async function fetchCall(
79	  callId: string,
80	  deps: CalleDeps,
81	): Promise<CallTaskFixture> {
82	  if (!callId) throw new Error("poll requires a CALL-E call id");
83	  const response = await deps.fetch(
84	    `${deps.calleApiBase.replace(/\/+$/, "")}/v1/calls/${encodeURIComponent(callId)}`,
85	    { headers: { authorization: `Bearer ${deps.calleApiKey}` } },
86	  );
87	  if (!response.ok) throw new Error(`CALL-E re-fetch returned HTTP ${response.status}`);
88	  const value: unknown = await response.json();
89	  if (typeof value !== "object" || value === null) {
90	    throw new Error("CALL-E re-fetch returned no call task");
91	  }
92	  const call = value as Partial<CallTaskFixture>;
93	  if (typeof call.id !== "string" || typeof call.status !== "string") {
94	    throw new Error("CALL-E re-fetch response missing id or status");
95	  }
96	  if (call.id !== callId) {
97	    throw new Error(`CALL-E re-fetch returned ${call.id} for ${callId}`);
98	  }
99	  return call as CallTaskFixture;
100	}
101	
102	async function readRun(deps: CalleDeps, runId: string): Promise<RunRow | null> {
103	  const query = new URLSearchParams({
104	    select: "id,state,calle_call_id,dispatched_at,poll_after",
105	    id: `eq.${runId}`,
106	    limit: "1",
107	  });
108	  const response = await deps.fetch(restUrl(deps.apiUrl, "call_runs", query.toString()), {
109	    headers: serviceHeaders(deps.serviceRoleKey),
110	  });
111	  if (!response.ok) throw new Error("call_runs poll read failed");
112	  const rows = await response.json() as RunRow[];
113	  return rows[0] ?? null;
114	}
115	
116	/**
117	 * Applies a patch only while the run is still pending, and reports whether
118	 * this caller was the one that won. Returning the representation is what makes
119	 * the loss observable rather than assumed.
120	 */
121	async function patchPendingRun(
122	  deps: CalleDeps,
123	  runId: string,
124	  patch: Record<string, unknown>,
125	): Promise<boolean> {
126	  const query = new URLSearchParams({ id: `eq.${runId}`, state: PENDING_STATES });
127	  const response = await deps.fetch(restUrl(deps.apiUrl, "call_runs", query.toString()), {
128	    method: "PATCH",
129	    headers: serviceHeaders(deps.serviceRoleKey, "return=representation"),
130	    body: JSON.stringify(patch),
131	  });
132	  if (!response.ok) throw new Error("call_runs poll update failed");
133	  const rows = await response.json() as unknown[];
134	  return Array.isArray(rows) && rows.length === 1;
135	}
136	
137	function failure(code: string, message: string): Record<string, string> {
138	  return { failure_code: code, failure_message: message };
139	}
140	
141	async function reschedule(
142	  deps: CalleDeps,
143	  runId: string,
144	  callId: string | null,
145	  detail: Record<string, string | number | boolean | null>,
146	): Promise<void> {
147	  const pollAfter = new Date(deps.now().getTime() + POLL_INTERVAL_MS).toISOString();
148	  const won = await patchPendingRun(deps, runId, { poll_after: pollAfter });
149	  if (!won) return;
150	  await recordCallEvent(runId, "polled", { calle_call_id: callId, ...detail }, deps);
151	}
152	
153	/**
154	 * Advances one pending run by one poll pass. A transport failure, a provider
155	 * error or an unparseable body reschedules the next pass instead of throwing,
156	 * so one poisoned run cannot fail the whole tick.
157	 */
158	export async function pollRun(run: PollableRun, deps: CalleDeps): Promise<void> {
159	  const current = await readRun(deps, run.id);
160	  // The webhook may have terminalised this run between the tick's read and
161	  // this call. That is the race, and losing it is a no-op.
162	  if (!current || current.state !== "dispatched" && current.state !== "awaiting_result") {
163	    return;
164	  }
165	
166	  if (!current.calle_call_id) {
167	    const won = await patchPendingRun(deps, run.id, {
168	      state: "failed",
169	      disposition: "not_answered",
170	      calle_failure: failure("poll_unavailable", "run has no CALL-E call id to poll"),
171	    });
172	    if (won) {
173	      await recordCallEvent(
174	        run.id,
175	        "polled",
176	        { calle_call_id: null, state: "failed", failure_reason: "run has no CALL-E call id to poll" },
177	        deps,
178	      );
179	    }
180	    return;
181	  }
182	
183	  const dispatchedAt = current.dispatched_at ?? current.poll_after;
184	  if (dispatchedAt) {
185	    const deadline = new Date(dispatchedAt).getTime() + POLL_GIVE_UP_MS;
186	    if (Number.isFinite(deadline) && deps.now().getTime() > deadline) {
187	      const won = await patchPendingRun(deps, run.id, {
188	        state: "failed",
189	        disposition: "not_answered",
190	        calle_failure: failure("poll_timeout", "CALL-E never reported a terminal state"),
191	      });
192	      if (won) {
193	        await recordCallEvent(
194	          run.id,
195	          "polled",
196	          { calle_call_id: current.calle_call_id, state: "failed", failure_reason: "poll_timeout" },
197	          deps,
198	        );
199	      }
200	      return;
201	    }
202	  }
203	
204	  let call: CallTaskFixture;
205	  try {
206	    call = await fetchCall(current.calle_call_id, deps);
207	  } catch (error) {
208	    await reschedule(deps, run.id, current.calle_call_id, {
209	      state: current.state,
210	      outcome: "refetch_failed",
211	      failure_reason: error instanceof Error ? error.message : "unknown error",
212	    });
213	    return;
214	  }
215	
216	  const terminal = terminalStateFor(call.status);
217	  if (!terminal) {
218	    await reschedule(deps, run.id, call.id, { state: call.status, outcome: "pending" });
219	    return;
220	  }
221	
222	  const failureCode = call.failure_code;
223	  const patch: Record<string, unknown> = {
224	    state: terminal,
225	    calle_confidence: call.completion_confidence,
226	    calle_failure: failureCode ? failure(failureCode, call.failure_message ?? "") : null,
227	    poll_after: null,
228	  };
229	  const won = await patchPendingRun(deps, run.id, patch);
230	  if (!won) return;
231	  await recordCallEvent(
232	    run.id,
233	    "polled",
234	    { calle_call_id: call.id, state: terminal, outcome: "terminal" },
235	    deps,
236	  );
237	}
238	
239	const testFn = (Deno as { test?: (name: string, fn: () => void | Promise<void>) => void }).test;
240	if (typeof testFn === "function") {
241	  const NOW = new Date("2026-09-13T10:00:00.000Z");
242	  const RUN = "11111111-1111-4111-8111-111111111111";
243	  const CALL = "call_poll_1";
244	
245	  type Seen = { method: string; url: string; body: unknown };
246	
247	  const depsFor = (
248	    fetchImpl: typeof fetch,
249	    now: Date = NOW,
250	  ): CalleDeps => ({
251	    apiUrl: "https://orma-api.test",
252	    serviceRoleKey: "service-key",
253	    calleApiBase: "https://api.call-e.test",
254	    calleApiKey: "calle-key",
255	    webhookUrl: "https://orma-api.test/functions/v1/calle-webhook/secret",
256	    fetch: fetchImpl,
257	    now: () => now,
258	  });
259	
260	  /** Every mock branches on method and path and throws on anything else, so no
261	   * test can reach a real service and no unexpected call can pass unnoticed. */
262	  const driver = (options: {
263	    run: Partial<RunRow> & { id: string; state: string };
264	    call?: unknown;
265	    callStatus?: number;
266	    patchWins?: boolean;
267	    callThrows?: boolean;
268	  }) => {
269	    const seen: Seen[] = [];
270	    const events: { kind: string; detail: Record<string, unknown> }[] = [];
271	    const fetchImpl: typeof fetch = async (input, init) => {
272	      const request = new Request(input, init);
273	      const url = new URL(request.url);
274	      const body = init?.body ? JSON.parse(init.body as string) as Record<string, unknown> : null;
275	      seen.push({ method: request.method, url: request.url, body });
276	      if (url.host === "api.call-e.test") {
277	        if (options.callThrows) throw new Error("network down");
278	        if (options.callStatus && options.callStatus >= 400) {
279	          return new Response(null, { status: options.callStatus });
280	        }
281	        return Response.json(options.call ?? { id: CALL, status: "in_progress" });
282	      }
283	      if (url.host === "orma-api.test" && url.pathname === "/rest/v1/call_runs") {
284	        if (request.method === "GET") {
285	          return Response.json([{ calle_call_id: CALL, dispatched_at: NOW.toISOString(), poll_after: null, ...options.run }]);
286	        }
287	        if (request.method === "PATCH") {
288	          return Response.json(options.patchWins === false ? [] : [{ id: options.run.id }]);
289	        }
290	      }
291	      if (url.pathname === "/rest/v1/call_events" && request.method === "POST") {
292	        events.push(body as { kind: string; detail: Record<string, unknown> });
293	        return new Response(null, { status: 201 });
294	      }
295	      throw new Error(`unexpected request ${request.method} ${request.url}`);
296	    };
297	    return { seen, events, fetchImpl };
298	  };
299	
300	  testFn("a pending call reschedules the next pass instead of finalising", async () => {
301	    const { seen, events, fetchImpl } = driver({
302	      run: { id: RUN, state: "awaiting_result" },
303	      call: { id: CALL, status: "in_progress" },
304	    });
305	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
306	    const patch = seen.find((entry) => entry.method === "PATCH");
307	    const body = patch?.body as { poll_after?: string; state?: string };
308	    if (!patch) throw new Error("a pending poll must persist the next poll time");
309	    if (body.state !== undefined) throw new Error("a pending poll must not write a terminal state");
310	    if (body.poll_after !== new Date(NOW.getTime() + POLL_INTERVAL_MS).toISOString()) {
311	      throw new Error("the next pass must be ten seconds out");
312	    }
313	    if (!seen.some((entry) => entry.method === "GET" && entry.url.includes("/v1/calls/" + CALL))) {
314	      throw new Error("a pending poll must re-fetch the authoritative call");
315	    }
316	    if (events.length !== 1 || events[0].kind !== "polled") {
317	      throw new Error("a pending poll must record exactly one polled event");
318	    }
319	  });
320	
321	  testFn("a completed call terminalises the run and leaves finalisation alone", async () => {
322	    const { seen, events, fetchImpl } = driver({
323	      run: { id: RUN, state: "dispatched" },
324	      call: { id: CALL, status: "completed", completion_confidence: { score: 0.9, label: "high" }, failure_code: null },
325	    });
326	    await pollRun({ id: RUN, state: "dispatched", poll_after: null }, depsFor(fetchImpl));
327	    const patch = seen.find((entry) => entry.method === "PATCH");
328	    const body = patch?.body as Record<string, unknown>;
329	    if (body.state !== "completed") throw new Error("a completed call must move the run to completed");
330	    if ("completed_at" in body) {
331	      throw new Error("the poll must not set completed_at, because the finaliser owns it");
332	    }
333	    if (!patch?.url.includes("state=in.%28dispatched%2Cawaiting_result%29")) {
334	      throw new Error("the terminal write must only match a still-pending run");
335	    }
336	    if (events[0]?.detail.state !== "completed" || events[0]?.detail.calle_call_id !== CALL) {
337	      throw new Error("the terminal event must name the provider id and the authoritative state");
338	    }
339	  });
340	
341	  testFn("a failed call records the failure the provider reported", async () => {
342	    const { events, fetchImpl } = driver({
343	      run: { id: RUN, state: "awaiting_result" },
344	      call: { id: CALL, status: "failed", failure_code: "no_answer", failure_message: "recipient did not pick up" },
345	    });
346	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
347	    if (events[0]?.detail.state !== "failed") throw new Error("a failed call must move the run to failed");
348	  });
349	
350	  testFn("a run the webhook already terminalised is a no-op", async () => {
351	    const { seen, events, fetchImpl } = driver({ run: { id: RUN, state: "completed" } });
352	    await pollRun({ id: RUN, state: "completed", poll_after: null }, depsFor(fetchImpl));
353	    if (seen.some((entry) => entry.url.includes("api.call-e.test"))) {
354	      throw new Error("a terminal run must not be re-fetched");
355	    }
356	    if (seen.some((entry) => entry.method === "PATCH")) {
357	      throw new Error("a terminal run must not be written");
358	    }
359	    if (events.length !== 0) throw new Error("a terminal run must record nothing");
360	  });
361	
362	  testFn("losing the race writes nothing", async () => {
363	    const { events, fetchImpl } = driver({
364	      run: { id: RUN, state: "awaiting_result" },
365	      call: { id: CALL, status: "completed" },
366	      patchWins: false,
367	    });
368	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
369	    if (events.length !== 0) {
370	      throw new Error("the loser of the race must record no timeline row");
371	    }
372	  });
373	
374	  testFn("a provider id that disagrees with the run is rejected", async () => {
375	    const { events, fetchImpl } = driver({
376	      run: { id: RUN, state: "awaiting_result" },
377	      call: { id: "call_someone_else", status: "completed" },
378	    });
379	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
380	    if (events.length !== 1 || events[0].detail.outcome !== "refetch_failed") {
381	      throw new Error("a mismatched provider id must reschedule, not terminalise");
382	    }
383	  });
384	
385	  testFn("a transport failure reschedules and never throws out of the tick", async () => {
386	    const { events, fetchImpl } = driver({
387	      run: { id: RUN, state: "awaiting_result" },
388	      callThrows: true,
389	    });
390	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
391	    if (events.length !== 1 || events[0].kind !== "polled" || events[0].detail.outcome !== "refetch_failed") {
392	      throw new Error("a transport failure must reschedule with a recorded reason");
393	    }
394	  });
395	
396	  testFn("a run past the give-up window is failed with a reason", async () => {
397	    const stale = { id: RUN, state: "awaiting_result", dispatched_at: new Date(NOW.getTime() - POLL_GIVE_UP_MS - 1).toISOString() };
398	    const { seen, events, fetchImpl } = driver({ run: stale });
399	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
400	    const patch = seen.find((entry) => entry.method === "PATCH");
401	    const body = patch?.body as { state?: string; calle_failure?: { failure_code?: string } };
402	    if (body.state !== "failed") throw new Error("a lost call must not poll forever");
403	    if (body.calle_failure?.failure_code !== "poll_timeout") {
404	      throw new Error("giving up must name the reason on the run");
405	    }
406	    if (seen.some((entry) => entry.url.includes("api.call-e.test"))) {
407	      throw new Error("a run past its window must not re-fetch");
408	    }
409	    if (events[0]?.detail.failure_reason !== "poll_timeout") {
410	      throw new Error("the timeline must name where it stopped");
411	    }
412	  });
413	
414	  testFn("a run without a provider id is failed rather than polled forever", async () => {
415	    const { seen, events, fetchImpl } = driver({
416	      run: { id: RUN, state: "awaiting_result", calle_call_id: null },
417	    });
418	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
419	    if (seen.some((entry) => entry.url.includes("api.call-e.test"))) {
420	      throw new Error("a run without a provider id cannot be polled");
421	    }
422	    if (events[0]?.detail.failure_reason !== "run has no CALL-E call id to poll") {
423	      throw new Error("the absence of a provider id must be visible on the timeline");
424	    }
425	  });
426	
427	  testFn("terminalStateFor maps only provider terminal states", () => {
428	    if (terminalStateFor("completed") !== "completed") throw new Error("completed must be terminal");
429	    if (terminalStateFor("failed") !== "failed") throw new Error("failed must be terminal");
430	    if (terminalStateFor("canceled") !== "canceled") throw new Error("canceled must be terminal");
431	    if (terminalStateFor("queued") !== null) throw new Error("queued is not terminal");
432	    if (terminalStateFor("in_progress") !== null) throw new Error("in_progress is not terminal");
433	  });
434	}
