76	export function webhookSecretsMatch(presented: string, expected: string): boolean {
77	  const encoder = new TextEncoder();
78	  const left = encoder.encode(presented);
79	  const right = encoder.encode(expected);
80	  if (left.length !== right.length) return false;
81	  let diff = 0;
82	  for (let index = 0; index < left.length; index++) diff |= left[index] ^ right[index];
83	  return diff === 0;
84	}
