100	export function parseWebhookEnvelope(body: string, headerEventId: string): WebhookEnvelope | null {
101	  if (!EVENT_ID_PATTERN.test(headerEventId)) return null;
102	  let value: unknown;
103	  try {
104	    value = JSON.parse(body);
105	  } catch {
106	    return null;
107	  }
108	  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
109	  const envelope = value as Partial<WebhookEnvelope>;
110	  if (
111	    envelope.id !== headerEventId ||
112	    typeof envelope.id !== "string" ||
113	    typeof envelope.type !== "string" ||
114	    !TERMINAL_EVENT_TYPES.has(envelope.type) ||
115	    typeof envelope.created_at !== "string" ||
116	    Number.isNaN(Date.parse(envelope.created_at)) ||
117	    !envelope.data ||
118	    typeof envelope.data !== "object" ||
119	    typeof envelope.data.id !== "string" ||
120	    !CALL_ID_PATTERN.test(envelope.data.id)
121	  ) return null;
122	  return envelope as WebhookEnvelope;
123	}
