212	    method: "PATCH",
213	    headers: serviceHeaders(deps.serviceRoleKey, "return=representation"),
214	    body: JSON.stringify({ state, poll_after: null }),
215	  });
216	  if (!response.ok) throw new Error("call run terminalisation failed");
217	  const rows = await response.json() as unknown[];
218	  return Array.isArray(rows) && rows.length === 1;
