236	export function createWebhookHandler(deps: WebhookDeps): (request: Request) => Promise<Response> {
237	  return async (request) => {
238	    if (request.method !== "POST") {
239	      return new Response(null, { status: 405, headers: { allow: "POST" } });
240	    }
241	    const presented = presentedWebhookSecret(new URL(request.url).pathname);
242	    if (!presented || !webhookSecretsMatch(presented, deps.webhookSecret)) {
243	      return new Response(null, { status: 401 });
244	    }
245	    const headerEventId = request.headers.get(EVENT_ID_HEADER);
246	    if (!headerEventId) return new Response(null, { status: 400 });
247	    try {
248	      const body = await request.text();
249	      if (new TextEncoder().encode(body).byteLength > MAX_BODY_BYTES) {
250	        return new Response(null, { status: 413 });
251	      }
252	      const envelope = parseWebhookEnvelope(body, headerEventId);
253	      if (!envelope) return new Response(null, { status: 400 });
254	      await insertPendingEvent(deps, envelope.id);
255	      if (!await claimPendingEvent(deps, envelope.id)) return new Response(null, { status: 200 });
256	      try {
257	        const call = await fetchAuthoritativeCall(deps, envelope.data.id);
258	        if (!call || !await hasMatchingOrmaRun(deps, call)) {
259	          await setEventState(deps, envelope.id, IGNORED);
260	          return new Response(null, { status: 200 });
261	        }
262	        // Persist the transition before the timeline claims it, so a failed
263	        // write never leaves an entry asserting a state that never landed.
264	        // The event row is released to pending below, so this is retried.
265	        await terminaliseFromRefetch(deps, call);
266	        const eventDeps = { apiUrl: deps.apiUrl, serviceRoleKey: deps.serviceRoleKey, fetch: deps.fetch };
267	        await recordCallEvent(
268	          call.metadata.call_run_id,
269	          "webhook_received",
270	          { calle_call_id: call.id, event_type: envelope.type },
271	          eventDeps,
272	        );
273	        await recordCallEvent(
274	          call.metadata.call_run_id,
275	          "refetched",
276	          { calle_call_id: call.id, event_type: envelope.type, state: call.status },
277	          eventDeps,
278	        );
279	        await setEventState(deps, envelope.id, REFETCHED);
280	        return new Response(null, { status: 200 });
281	      } catch (error) {
282	        try {
283	          await setEventState(deps, envelope.id, PENDING);
284	        } catch (releaseError) {
285	          console.error("calle webhook event release failed", releaseError instanceof Error ? releaseError.message : "unknown error");
286	        }
287	        throw error;
288	      }
289	    } catch (error) {
290	      console.error("calle webhook re-fetch failed", error instanceof Error ? error.message : "unknown error");
291	      return new Response(null, { status: 500 });
292	    }
293	  };
294	}
