/**
 * T2.5 remediation round 1 live pins. Drives the working-tree tick handler,
 * webhook handler and pollRun against the scratch stack. Only the CALL-E
 * transport is stubbed. The script prints nothing that counts as evidence.
 * Every claim is re-read afterwards with psql by the remediator.
 */
import { createTickHandler, depsFromEnv as tickDepsFromEnv } from "/home/nryn/work/orma/supabase/functions/tick/index.ts";
import { createWebhookHandler, depsFromEnv as webhookDepsFromEnv } from "/home/nryn/work/orma/supabase/functions/calle-webhook/index.ts";
import { depsFromEnv as calleDepsFromEnv } from "/home/nryn/work/orma/supabase/functions/_shared/calle.ts";
import { pollRun, POLL_GIVE_UP_MS } from "/home/nryn/work/orma/supabase/functions/_shared/poll.ts";

const API = Deno.env.get("ORMA_API_URL")!;
const KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const SECRET = Deno.env.get("ORMA_WEBHOOK_SECRET")!;
const USER = "00000000-0000-4000-8000-000000000001";
if (Deno.env.get("CALLE_API_BASE") !== "https://api.call-e.test") throw new Error("refusing: CALLE_API_BASE is not the stub host");

const headers = { apikey: KEY, authorization: `Bearer ${KEY}`, "content-type": "application/json" };
const rest = (path: string, init: RequestInit = {}) =>
  fetch(`${API}/rest/v1/${path}`, { ...init, headers: { ...headers, ...(init.headers ?? {}) } });

const fakes = new Map<string, string>();
const runByCall = new Map<string, string>();
const stub: typeof fetch = async (input, init) => {
  const request = new Request(input, init);
  const url = new URL(request.url);
  if (url.host === "api.call-e.test") {
    if (request.method !== "GET") return new Response(null, { status: 599 });
    const id = url.pathname.split("/").pop()!;
    const status = fakes.get(id);
    if (!status) return new Response(null, { status: 404 });
    return Response.json({ id, status, metadata: { call_run_id: runByCall.get(id) } });
  }
  if (url.origin !== new URL(API).origin) throw new Error(`refusing outbound request to ${url.host}`);
  return await fetch(request);
};

const env = (k: string) => Deno.env.get(k);
async function createRun(label: string, patch: Record<string, unknown>, callId: string | null): Promise<string> {
  const id = crypto.randomUUID();
  if (callId) runByCall.set(callId, id);
  const response = await rest("call_runs", {
    method: "POST",
    body: JSON.stringify({
      id, user_id: USER, local_date: "2026-09-13", part_of_day: `rem-${label}`,
      scheduled_for: new Date().toISOString(), idempotency_key: `rem-t25-${label}-${id}`,
      calle_call_id: callId, ...patch,
    }),
  });
  if (!response.ok) throw new Error(`create ${label} failed ${response.status} ${await response.text()}`);
  console.log(`${label}=${id}`);
  return id;
}

const mode = Deno.args[0];

if (mode === "H") {
  const now = Date.now();
  await createRun("H-terminal", { state: "completed", completed_at: null, dispatched_at: new Date(now - 180_000).toISOString(), poll_after: null }, "call_rem_h_term");
  await createRun("H-sibling", { state: "awaiting_result", dispatched_at: new Date(now - 120_000).toISOString(), poll_after: new Date(now - 1_000).toISOString() }, "call_rem_h_sib");
  fakes.set("call_rem_h_sib", "completed");
  const response = await createTickHandler(tickDepsFromEnv(env, stub))(new Request(`${API}/functions/v1/tick`, { method: "POST" }));
  // The HTTP status is the handler's own answer to the cron caller, so it is the artifact under test.
  console.log(`H-tick-status=${response.status}`);
}

if (mode === "M") {
  const created = Date.now() - POLL_GIVE_UP_MS + 3 * 60_000; // window closes three minutes from now
  const id = await createRun("M-nodispatch", {
    state: "awaiting_result", dispatched_at: null, created_at: new Date(created).toISOString(),
    poll_after: new Date().toISOString(),
  }, "call_rem_m");
  fakes.set("call_rem_m", "in_progress");
  const base = calleDepsFromEnv(env, stub);
  let clock = Date.now();
  for (let pass = 1; pass <= 10; pass++) {
    clock += 60_000;
    await pollRun({ id, state: "awaiting_result", poll_after: null }, { ...base, now: () => new Date(clock) });
    console.log(`M-pass=${pass} simulated_minutes_past_creation=${Math.round((clock - created) / 60_000)}`);
  }
}

if (mode === "L") {
  const id = await createRun("L-race", { state: "awaiting_result", dispatched_at: new Date().toISOString(), poll_after: new Date().toISOString() }, "call_rem_l");
  fakes.set("call_rem_l", "completed");
  await pollRun({ id, state: "awaiting_result", poll_after: null }, calleDepsFromEnv(env, stub));
  fakes.set("call_rem_l", "failed");
  const eventId = `evt_rem_${crypto.randomUUID().slice(0, 8)}`;
  const response = await createWebhookHandler(webhookDepsFromEnv(env, stub))(new Request(`${API}/functions/v1/calle-webhook/${SECRET}`, {
    method: "POST", headers: { "call-e-event-id": eventId },
    body: JSON.stringify({ id: eventId, type: "call.failed", created_at: new Date().toISOString(), data: { id: "call_rem_l" } }),
  }));
  console.log(`L-webhook-status=${response.status} L-event=${eventId}`);
}
